<script lang="ts">let { entry }=$props<{entry:any}>();const parse=(v:string)=>{try{return JSON.parse(v)as string[]}catch{return[]}};const items=$derived([{label:'Collocations',values:parse(entry.collocations)},{label:'Word family',values:parse(entry.wordFamily)},{label:'Synonyms',values:parse(entry.synonyms)},{label:'Antonyms',values:parse(entry.antonyms)}].filter(x=>x.values.length));</script>
{#if entry.usageNote||items.length||entry.register}<details><summary>More language notes</summary><div>{#if entry.usageNote}<p><b>Usage</b> {entry.usageNote}</p>{/if}{#if entry.register}<p><b>Register</b> {entry.register}</p>{/if}{#each items as item}<p><b>{item.label}</b> {item.values.join(' · ')}</p>{/each}</div></details>{/if}
<style>details{font-size:12px;color:var(--text-secondary)}summary{cursor:pointer;color:var(--text-muted)}details div{display:grid;gap:7px;margin-top:10px}b{color:var(--text-primary);margin-right:8px}</style>
